INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-001', 'PET Beverage Bottle (Type 1)', '["pet bottle", "soda bottle", "plastic bottle", "water bottle", "beverage bottle"]', 'Plastic', 'Dry (Blue)', 'Empty liquid, rinse residue, crush flat, and replace cap before placing in dry bin.', '100% recyclable into polyester fiber yarn, geotextiles, strapping, and new bottle packaging.', 'Do not incinerate; burning releases harmful toxic hydrocarbons.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-002', 'HDPE Milk & Juice Jug (Type 2)', '["hdpe bottle", "milk jug", "juice container", "opaque bottle"]', 'Plastic', 'Dry (Blue)', 'Rinse with water, drain, flatten to save volume, and place in blue dry bin.', 'Recycled into drainage pipes, recycling bins, plastic lumber, and detergent bottles.', 'Ensure bottle is free of sour milk curds to prevent batch odor contamination.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-003', 'HDPE Shampoo & Detergent Bottle', '["shampoo bottle", "soap bottle", "detergent bottle", "bleach bottle"]', 'Plastic', 'Dry (Blue)', 'Pump out excess soap, rinse thoroughly, and recap.', 'High recycling value; reprocessed into composite decking, crates, and new non-food containers.', 'Rinse out concentrated detergents before discarding to protect sanitation workers'' skin.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-004', 'PVC Water Pipe Offcuts (Type 3)', '["pvc pipe", "plumbing pipe", "plastic conduit", "drain pipe"]', 'Plastic', 'Dry (Blue)', 'Bundle cleanly into lengths under 1 meter and hand over at dry waste recovery centers.', 'Mechanically ground into vinyl flooring, mud flaps, and non-potable conduit piping.', 'Never burn PVC. Combustion produces deadly hydrogen chloride gas and dioxins.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-005', 'LDPE Grocery Carry Bag (Type 4)', '["plastic bag", "carry bag", "grocery bag", "polythene", "shopping bag"]', 'Plastic', 'Dry (Blue)', 'Shake out food debris, gather multiple clean bags into a single ball, and place in dry bin.', 'Pelletized into recycled film, construction moisture barriers, and composite trash bags.', 'Banned single-use polythene bags under 120 microns should be surrendered at municipal collection points.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-006', 'LDPE Bubble Wrap & Cushioning', '["bubble wrap", "packaging film", "air pouch", "cushioning film"]', 'Plastic', 'Dry (Blue)', 'Pop bubbles to reduce volume and pack with clean plastic film recycling.', 'Recycled into composite lumber and protective building insulation.', 'Ensure tape labels are trimmed off if possible.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-007', 'PP Food Delivery Container (Type 5)', '["takeaway container", "biryani box", "plastic tub", "curry container"]', 'Plastic', 'Dry (Blue)', 'Wash away oily grease using cold soapy water, dry completely, and place in blue bin.', 'Reprocessed into automotive parts, battery cases, broom bristles, and industrial buckets.', 'Unwashed greasy containers attract vermin and contaminate paper recycling bales.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-008', 'PP Bottle Caps & Closures', '["bottle cap", "plastic cap", "screw cap", "jar lid"]', 'Plastic', 'Dry (Blue)', 'Leave screwed securely onto empty crushed bottles so they do not fall through MRF sorting screens.', 'Shredded and molded into industrial bins, plant pots, and battery casings.', 'Loose caps are easily lost in transit; keep attached to mother container.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-009', 'PP Straws & Disposable Cutlery', '["plastic straw", "plastic spoon", "plastic fork", "disposable cutlery"]', 'Plastic', 'Dry (Blue)', 'Rinse food scraps and collect in a dry container. Single-use plastic items must be phased out.', 'Low recyclability index due to small size; processed into Refuse Derived Fuel (RDF) for cement kilns.', 'Avoid single-use plastics; switch to stainless steel or bamboo cutlery.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-010', 'PS Disposable Coffee Cup Lid (Type 6)', '["coffee lid", "cup lid", "plastic lid"]', 'Plastic', 'Dry (Blue)', 'Rinse coffee stains and stack together in dry recyclables.', 'Processed into extruded insulation panels and stationary trays.', 'Do not microwave polystyrene as styrene monomers can leach into hot liquids.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-011', 'Expanded Polystyrene Foam (Thermocol)', '["thermocol", "styrofoam", "eps foam", "appliance packing"]', 'Plastic', 'Dry (Blue)', 'Keep clean and dry. Deliver in bulk to municipal Material Recovery Facilities (MRF) equipped with foam densifiers.', 'Hot-melt densification converts lightweight foam into dense polystyrene ingots for picture frames.', 'Never burn thermocol outdoors. Emits thick black toxic smoke containing styrene vapors.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-012', 'Multi-Layer Plastic Snack Wrapper (Type 7)', '["chips packet", "biscuit wrapper", "crisp pouch", "metallized film"]', 'Plastic', 'Dry (Blue)', 'Ensure crumb-free and completely dry. Deposit in dry waste bin for co-processing.', 'Sent to authorized cement plants for co-processing as Refuse Derived Fuel (RDF) replacing coal.', 'Cannot be melted down mechanically due to bonded aluminum-plastic layers.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-013', 'PET Clamshell Fruit Container', '["clamshell", "fruit box", "clear berry box", "transparent container"]', 'Plastic', 'Dry (Blue)', 'Rinse fruit juices, remove paper adhesive sticker, and crush flat.', 'Processed with bottle grade flakes for thermoforming new trays.', 'Ensure adhesive labels with heavy rubber glue are removed if possible.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-014', 'Toothpaste Tube (Laminated Plastic/Alloy)', '["toothpaste tube", "ointment tube", "creme tube"]', 'Plastic', 'Dry (Blue)', 'Squeeze out all remaining paste, cut open to rinse, and place in dry bin.', 'Modern multi-material tubes are shredded for plastic-aluminum separation or RDF.', 'Do not throw in wet waste; residual paste does not make it compostable.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-015', 'Plastic Cling Wrap & Saran Film', '["cling film", "cling wrap", "food wrap", "plastic film"]', 'Plastic', 'Dry (Blue)', 'Clean food oils with water, bundle into a dry recycling ball.', 'Blended with LDPE feedstock for industrial tarpaulins and garbage liners.', 'Keep separate from bio-waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-016', 'Plastic Plant Pots & Seedling Trays', '["plant pot", "seedling tray", "garden pot"]', 'Plastic', 'Dry (Blue)', 'Knock out dried dirt and potting soil, rinse, and place in dry bin.', 'Melted into heavy duty utility buckets and agricultural drainage pipes.', 'Shake off soil thoroughly as dirt abrades shredding blades at recycling plants.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-017', 'Plastic Hangers (Polypropylene/Polystyrene)', '["clothes hanger", "plastic hanger", "coat hanger"]', 'Plastic', 'Dry (Blue)', 'Separate metal hook wire if detached; place plastic frame in blue bin.', 'Recycled into shipping pallets and outdoor storage bins.', 'Damaged hangers should not be thrown into general mixed rubbish.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-018', 'Plastic Milk Pouch (LDPE Rinsed)', '["milk pouch", "milk packet", "curd packet"]', 'Plastic', 'Dry (Blue)', 'Cut only a small corner (avoid detaching tip completely), rinse milk fat thoroughly, and dry.', 'High grade LDPE is eagerly purchased by recyclers for pipe extrusion.', 'Unrinsed milk pouches generate foul bacterial odors within 12 hours.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-019', 'Acrylic Sheet Offcuts (Perspex/Plexiglass)', '["acrylic", "perspex", "plexiglass", "clear sheet"]', 'Plastic', 'Dry (Blue)', 'Stack safely without jagged edges and deposit at recycling centers.', 'Depolymerized via thermal cracking back into liquid methyl methacrylate (MMA).', 'Wear protective gloves when handling cracked sheets.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-020', 'Polycarbonate Water Dispenser Bottle (20L)', '["water can", "bisleri jar", "water dispenser bottle", "20 liter jar"]', 'Plastic', 'Dry (Blue)', 'Return to water supplier for deposit reuse (can be reused up to 50 times); damaged cans go to blue bin.', 'Shredded for automotive headlamp lenses, safety goggles, and electronic housings.', 'Inspect for micro-cracks before refilling.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-021', 'Plastic Toothbrush (Manual)', '["toothbrush", "nylon toothbrush", "brush"]', 'Plastic', 'Dry (Blue)', 'Rinse bristles, pack with rigid plastics. Consider bamboo alternatives.', 'Handles (PP) are reprocessed into industrial park benches; bristles are incinerated.', 'Replace every 3 months; dispose in designated dry waste stream.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-022', 'Plastic Dispenser Pumps & Sprayer Heads', '["dispenser pump", "spray nozzle", "lotion pump"]', 'Plastic', 'Dry (Blue)', 'Unscrew from bottle. Contains small internal stainless steel spring.', 'Metal spring is separated magnetically after mechanical granulating.', 'Rinse residual lotion or sanitizer before discarding.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-023', 'Plastic Straws & Stirrers', '["straw", "plastic straw", "drink stirrer"]', 'Plastic', 'Dry (Blue)', 'Collect in a closed container so they do not blow away during transport.', 'Diverted to cement kilns for energy recovery (RDF).', 'Single-use plastic straws are prohibited under Plastic Waste Management Rules 2021.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-024', 'Plastic Mesh Produce Bags (Onion/Potato net)', '["mesh bag", "vegetable net", "onion sack", "produce mesh"]', 'Plastic', 'Dry (Blue)', 'Shake out vegetable skins and dry.', 'Extruded into heavy duty industrial mesh and construction fiber.', 'Do not mix with organic wet waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-025', 'Rigid Plastic Toy (Non-Electronic)', '["plastic toy", "lego brick", "toy car", "beach bucket"]', 'Plastic', 'Dry (Blue)', 'Remove any metal screws or batteries. If reusable, donate to charity; otherwise place in blue bin.', 'Blended ABS and PP are recycled into commercial utility boxes.', 'Ensure all electronic batteries are removed before disposal.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-026', 'Clear Glass Bottle (Soda-Lime)', '["glass bottle", "beer bottle", "soda glass", "beverage glass"]', 'Glass', 'Dry (Blue)', 'Rinse out residual beverage, let dry, and place carefully in blue dry bin.', '100% infinitely recyclable. Cullet glass melts at lower furnace temperatures, cutting emissions.', 'Never place broken glass loosely in trash bags; danger of lacerations to sanitation crew.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-027', 'Amber Glass Medicine & Chemical Bottle', '["amber bottle", "syrup bottle", "cough syrup bottle", "tincture bottle"]', 'Glass', 'Dry (Blue)', 'Ensure empty of all medicinal liquid, rinse safely, and deposit in glass collection bin.', 'Melted into new pharmaceutical-grade UV-protective amber packaging.', 'If bottle contains toxic chemo or cytotoxic drugs, treat as Hazardous Waste (Red Bin).', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-028', 'Green Wine & Olive Oil Glass Bottle', '["wine bottle", "olive oil bottle", "green glass"]', 'Glass', 'Dry (Blue)', 'Rinse oil residues with warm water, remove cork, and place in glass recycling stream.', 'Color-sorted and crushed into green cullet for new container manufacturing.', 'Keep color-separated where local sorting facilities request.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-029', 'Glass Food Jar (Jam, Pickle, Honey)', '["jam jar", "pickle jar", "honey jar", "mayonnaise jar", "mason jar"]', 'Glass', 'Dry (Blue)', 'Scrape food remnants, rinse with water, remove tin lid (lid goes in metal stream).', 'Melted and reformed into new glass jars indefinitely with zero degradation.', 'Do not leave sugary syrup inside; attracts pests and insects.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-030', 'Broken Window Panes & Sheet Glass', '["window glass", "flat glass", "broken pane", "window pane"]', 'Glass', 'Dry (Blue)', 'Wrap securely in thick multi-layered newspaper, tape closed, and label clearly ''BROKEN GLASS''.', 'Flat glass has different melting point than container glass; reprocessed into fiberglass and aggregate.', 'Handling without puncture-resistant gloves causes severe puncture injuries.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-031', 'Tempered Glass Screen Protector', '["screen guard", "tempered glass", "phone glass"]', 'Glass', 'Dry (Blue)', 'Wrap in paper and place in dry waste bin.', 'Composite silicone adhesive layer prevents bottle furnace recycling; sent to aggregate recycling.', 'Do not snap in half; shards can spray into eyes.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-032', 'Borosilicate Glass Cookware (Pyrex)', '["pyrex", "borosil", "baking dish", "heat resistant glass"]', 'Glass', 'Dry (Blue)', 'If broken, wrap safely in paper. Do NOT mix with regular bottle glass.', 'Higher melting point contaminates standard glass recycling furnaces; crushed for construction sand.', 'Cannot be processed in normal glass cullet furnaces.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-033', 'Glass Perfume & Cologne Bottle', '["perfume bottle", "scent bottle", "fragrance bottle"]', 'Glass', 'Dry (Blue)', 'Ensure fragrance is empty. Remove metallic spray nozzle with pliers if possible.', 'High clarity flint glass is remelted into luxury cosmetic containers.', 'Flammable alcohol vapors must be completely evaporated before transport.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-034', 'Glass Laboratory Beakers & Flasks', '["beaker", "lab flask", "test tube", "conical flask"]', 'Glass', 'Dry (Blue)', 'Decontaminate thoroughly with neutralizing wash before discarding.', 'Specialty chemical glass is downcycled into abrasive grit and industrial pavers.', 'Contaminated lab glassware must be autoclaved before municipal disposal.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-035', 'Glass Drinkware & Tumblers', '["glass tumbler", "water glass", "drinking glass", "chai glass"]', 'Glass', 'Dry (Blue)', 'Rinse and place in dry bin. If chipped or cracked, wrap in thick paper.', 'Contains lead or fluxes in some crystal variants; processed with specialty cullet.', 'Wrap chipped rims securely to avoid cut hazards.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-036', 'Mirrors & Silvered Glass Shards', '["mirror", "looking glass", "silvered glass"]', 'Glass', 'Dry (Blue)', 'Wrap in protective cardboard sheets. Do not commingle with container glass.', 'Silver/chemical backing paint prevents standard glass remelting; used in asphalt/concrete fillers.', 'Reflective shards cause deep puncture wounds if left exposed.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-037', 'Eyeglass & Spectacle Lenses', '["spectacle lens", "glasses lens", "optical lens"]', 'Glass', 'Dry (Blue)', 'Donate usable frames to vision charities; scratched lenses wrap in paper.', 'Polycarbonate and CR-39 resin lenses are separated for polymer recycling.', 'Optical coatings do not pose hazardous toxicity.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-038', 'Glass Marbles & Decorative Pebbles', '["marbles", "glass pebbles", "aquarium stones"]', 'Glass', 'Dry (Blue)', 'Collect in a sturdy box and donate or place in blue bin.', 'Easily melted down with general soda-lime glass cullet.', 'Choking hazard for young children; store securely.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-039', 'Glass Candle Jar (Wax Residue)', '["candle jar", "scented candle glass"]', 'Glass', 'Dry (Blue)', 'Pour boiling water into jar to melt and float residual wax out, wipe clean, place jar in blue bin.', 'Clean jars melt efficiently without smoky carbon residue in cullet furnaces.', 'Wax residue will cause furnace smoke if not removed.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-040', 'Glass Ampoules (Cosmetic/Medical Clean)', '["ampoule", "cosmetic ampoule", "serum vial"]', 'Glass', 'Dry (Blue)', 'Ensure empty. Wrap sharp snapped glass neck in adhesive tape.', 'High purity glass is sterilized and remelted.', 'Sharp edges require careful wrapping.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-041', 'Aluminum Beverage Can', '["soda can", "coke can", "beer can", "aluminum can", "tin can"]', 'Metal', 'Dry (Blue)', 'Rinse sweet liquid, crush vertically to minimize storage footprint, and toss into blue bin.', 'Recycling aluminum saves 95% of the energy needed to produce virgin metal from bauxite ore.', 'Ensure cans are drained to avoid sticky bacterial rot.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-042', 'Tinplate Steel Food & Soup Can', '["tin can", "canned food", "soup can", "tuna can", "baked beans can"]', 'Metal', 'Dry (Blue)', 'Rinse food grease, place lid inside the can, and lightly pinch can opening.', 'Separated rapidly via industrial electromagnets; melted into automotive steel sheet.', 'Sharp can lids pose severe cut hazard; push lid down inside can.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-043', 'Aluminum Foil & Takeaway Trays', '["aluminum foil", "silver foil", "foil tray", "food foil"]', 'Metal', 'Dry (Blue)', 'Wipe away gravy and oils. Roll multiple pieces into a compact aluminum sphere.', 'Pelletized foil melts into secondary aluminum casting ingots.', 'Heavily food-soiled foil should be rinsed or diverted if excessively charred.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-044', 'Copper Wire & Cable Scrap', '["copper wire", "electrical cable", "copper tubing", "stripped wire"]', 'Metal', 'Dry (Blue)', 'Coil neatly and deposit at an authorized electrical or metal scrap center.', 'High value commodity; electrolytic refining produces 99.99% pure cathode copper.', 'Do not burn plastic insulation off wire; open burning creates toxic furan and dioxin fumes.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-045', 'Brass Fittings, Valves & Door Hardware', '["brass valve", "brass tap", "door handle", "brass fitting"]', 'Metal', 'Dry (Blue)', 'Remove rubber washers or plastic sleeves; deposit with scrap metals.', 'Melted in foundry crucibles to produce new plumbing fixtures and hardware.', 'Heavy weight; store in durable collection bins.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-046', 'Aerosol Spray Can (Empty Deodorant/Insecticide)', '["deodorant can", "spray can", "insecticide can", "spray paint"]', 'Metal', 'Hazardous (Red)', 'Ensure completely depressurized and empty. Do NOT puncture or crush yourself.', 'Specialized facilities pierce under inert nitrogen to recover steel or aluminum canisters.', 'Residual propellants are pressurized volatile hydrocarbons; high explosion risk in trash compactor trucks.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-047', 'Steel Bottle Crowns & Metal Jar Lids', '["bottle cap metal", "crown cap", "metal lid", "pickle lid"]', 'Metal', 'Dry (Blue)', 'Collect inside a steel soup can and crimp closed so small caps do not jam sorting machinery.', 'Magnetically extracted and processed in electric arc furnaces.', 'Sharp crimped edges can cut fingers.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-048', 'Metal Cutlery & Cooking Utensils', '["stainless steel spoon", "fork", "knife", "metal ladle", "steel plate"]', 'Metal', 'Dry (Blue)', 'Donate usable utensils. Damaged items place in dry metal recycling stream.', 'Stainless steel contains nickel and chromium, retaining high scrap recovery value.', 'Wrap sharp kitchen knives in cardboard and tape before disposal.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-049', 'Iron & Steel Nails, Screws & Fasteners', '["nails", "screws", "nuts and bolts", "fasteners"]', 'Metal', 'Dry (Blue)', 'Put inside a metal tin or container to prevent puncturing collection bags.', 'Melted directly with general ferrous scrap in induction furnaces.', 'Loose nails puncture collection truck tires and injure sanitation workers.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-050', 'Galvanized Iron Roofing & Sheet Metal', '["galvanized sheet", "corrugated tin roof", "sheet metal"]', 'Metal', 'Dry (Blue)', 'Stack flat or roll with wire binding; deliver to municipal scrap depot.', 'Zinc coating is captured in baghouse filters during electric arc furnace melting.', 'Wear heavy leather work gloves when handling sharp galvanized edges.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-051', 'Metal Wire Coat Hangers', '["metal hanger", "wire hanger", "dry cleaner hanger"]', 'Metal', 'Dry (Blue)', 'Return to dry cleaners for reuse, or bundle together for metal collection.', 'Shredded for steel scrap re-melting.', 'Untangled loose hangers snag conveyer belts at recycling sorting plants.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-052', 'Aluminum Siding & Window Frames', '["window frame", "aluminum channel", "aluminum extrusion"]', 'Metal', 'Dry (Blue)', 'Remove glass panes, weatherstripping rubber, and steel screws.', 'Extrusion grade 6063 alloy is remelted into new architectural structural profiles.', 'Disassemble composite materials before delivery.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-053', 'Metal Keys (Brass & Nickel)', '["keys", "house key", "padlock key"]', 'Metal', 'Dry (Blue)', 'Place in dry metal bin. Consider metal scrap bin.', 'Smelted with copper and brass alloys.', 'De-identify any address tags before disposal.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-054', 'Empty Paint Cans (Dried Latex/Water-based)', '["paint can", "paint tin", "primer can"]', 'Metal', 'Dry (Blue)', 'Allow water-based paint residue to dry rock-hard under sun before placing in metal bin.', 'Steel cans are magnetically segregated and incinerated in smelting furnaces.', 'Liquid paint must NEVER be thrown in trash. Wet solvent paint is Hazardous (Red).', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-055', 'Lead Fishing Weights & Sinkers', '["lead sinker", "fishing weights", "lead weight"]', 'Metal', 'Hazardous (Red)', 'Do NOT throw in municipal trash. Hand over to hazardous waste or battery reclamation centers.', 'Secondary lead smelting plants refine lead for industrial batteries.', 'Toxic heavy metal. Wash hands thoroughly after handling. High neurotoxicity.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-056', 'Corrugated Cardboard Shipping Box', '["cardboard box", "amazon box", "shipping carton", "corrugated paper"]', 'Paper', 'Dry (Blue)', 'Remove plastic packaging tape, flatten box completely, keep dry.', 'Repulped into new kraft linerboard and cardboard boxes up to 7 times.', 'Do not allow boxes to get wet in rain; water weakens cellulose fibers and promotes mold.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-057', 'Old Newspapers & Newsprint', '["newspaper", "newsprint", "raddi", "daily paper"]', 'Paper', 'Dry (Blue)', 'Stack neatly, tie with cotton twine, keep dry in blue recycling stream.', 'De-inked and repulped into fresh newsprint, egg cartons, and paper towels.', 'Keep away from cooking oils and wet kitchen waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-058', 'Magazines & Glossy Catalogues', '["magazine", "catalogue", "brochure", "glossy paper"]', 'Paper', 'Dry (Blue)', 'Keep flat and dry. Plastic subscription wrappers must be removed and placed in plastic stream.', 'Kaolin clay coating is separated during flotation de-inking; fibers reused for printing paper.', 'Remove poly-wrap sleeves before recycling.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-059', 'Office Paper & Document Printouts', '["office paper", "printer paper", "a4 sheets", "documents"]', 'Paper', 'Dry (Blue)', 'Shred confidential papers. Remove metal binder clips (staples are acceptable).', 'High-grade bleached chemical pulp; recycled into premium writing paper and tissues.', 'Shredded paper should be placed inside a paper bag so it does not scatter in wind.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-060', 'Tetra Pak Aseptic Cartons (Milk/Juice)', '["tetra pak", "juice carton", "milk carton", "aseptic packaging"]', 'Paper', 'Dry (Blue)', 'Unfold corners, rinse milk/juice residue, flatten, and deposit in dry bin.', 'Specialized hydropulping separates 75% paper fiber for cartons and 25% PolyAl for roof tiles.', 'Unrinsed cartons turn sour and foul recycling facilities.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-061', 'Paper Grocery Bags & Kraft Sacks', '["paper bag", "kraft bag", "brown bag", "takeout paper bag"]', 'Paper', 'Dry (Blue)', 'Empty crumbs, fold flat, and recycle with dry paper.', 'Long kraft fibers add structural strength to recycled paper packaging.', 'Greasy paper bags contaminated with butter or oil belong in compost (Green Bin).', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-062', 'Egg Cartons (Molded Paper Pulp)', '["egg carton", "egg tray", "pulp carton"]', 'Paper', 'Dry (Blue)', 'Ensure clean without broken egg yolk stains. Can also be shredded for home composting.', 'Made from low-grade recycled newsprint; composts rapidly or recycled into molded pulp.', 'Egg cartons with broken raw egg leaks should be composted in wet bin.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-063', 'Phone Books & Yellow Pages Directories', '["phone book", "directory", "yellow pages"]', 'Paper', 'Dry (Blue)', 'Remove plastic wrap, keep dry with paper collection.', 'Processed into insulation cellulose, hydroseeding mulch, and packaging fillers.', 'Dry storage prevents mold growth.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-064', 'Paper Envelopes (With/Without Clear Window)', '["envelope", "letter envelope", "mail"]', 'Paper', 'Dry (Blue)', 'No need to cut out plastic address windows; screens filter film during pulping.', 'Recycled with mixed office papers.', 'Ensure paper contents are removed before recycling.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-065', 'Paperboard Cereal & Shoe Boxes', '["cereal box", "shoe box", "tissue box", "carton box"]', 'Paper', 'Dry (Blue)', 'Remove inner plastic liner bag (liner goes to plastic bin), flatten box.', 'Melted into recycled chipboard for book covers and puzzle boards.', 'Flattening preserves bin volume.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-066', 'Paper Towel & Toilet Paper Tubes', '["cardboard core", "toilet roll tube", "towel core"]', 'Paper', 'Dry (Blue)', 'Flatten core and place in dry bin or drop into home compost bin.', 'Repulped into cardboard boxes or molded egg cartons.', '100% biodegradable and recyclable.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-067', 'Wrapping Paper (Non-Metallic/Non-Glitter)', '["wrapping paper", "gift wrap", "gift paper"]', 'Paper', 'Dry (Blue)', 'Perform the scrunch test: if it stays crumpled, it is recyclable paper.', 'De-inked for low-grade paper products.', 'Foil, metallic, or glitter gift wrap cannot be recycled; throw in general waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-068', 'Thermal Cash Register Receipts', '["receipt", "bill", "thermal paper", "atm slip"]', 'Paper', 'Hazardous (Red)', 'Dispose in general or hazardous bin. Do NOT mix with paper recycling.', 'Coated with Bisphenol-A (BPA) or BPS chemical developers that contaminate paper pulp batches.', 'Contains endocrine-disrupting BPA chemicals; do not compost.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-069', 'Paper Coffee Cups (PE Lined)', '["coffee cup", "paper cup", "disposable cup"]', 'Paper', 'Dry (Blue)', 'Empty liquid. Separate plastic lid (lid to plastic). Take cup to MRF with poly-separation.', 'Polyethylene liner requires specialized high-consistency pulpers to strip plastic layer.', 'Consider bringing your own reusable thermal mug to coffee shops.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-070', 'Greasy Pizza Box (Cheese/Oil Stained)', '["pizza box", "takeout pizza carton"]', 'Paper', 'Wet (Green)', 'Tear off clean top lid for paper recycling (Blue Bin); tear oily bottom into wet compost (Green Bin).', 'Oil and melted cheese ruin paper slurry; composters break down organic grease easily.', 'Never put grease-soaked cardboard in blue paper bins.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-071', 'Raw Vegetable Peels & Scraps', '["vegetable waste", "onion skins", "potato peels", "carrot tops"]', 'Organic', 'Wet (Green)', 'Place directly into green bin or home composting pit without plastic bags.', 'Aerobic composting yields nutrient-dense organic humus in 45-60 days.', 'Do not wrap in plastic shopping bags before throwing into green bin.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-072', 'Citrus Rinds & Fruit Peels', '["orange peel", "lemon rind", "banana peel", "apple core"]', 'Organic', 'Wet (Green)', 'Chop into smaller pieces for faster composting rate.', 'Enriches compost with nitrogen, potassium, and beneficial bio-enzymes.', 'Excessive citrus in worm vermicomposters can harm earthworms; balance with brown leaves.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-073', 'Cooked Food Leftovers & Spoiled Meals', '["cooked food", "leftover rice", "curry waste", "spoiled food"]', 'Organic', 'Wet (Green)', 'Drain excess gravy/liquid into drain, place solid scraps in green bin.', 'Fed to municipal anaerobic biomethanation digesters to generate green electricity & Bio-CNG.', 'Cover compost caddy to prevent fruit fly and rodent infestation.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-074', 'Coffee Grounds & Paper Coffee Filters', '["coffee grounds", "used coffee", "filter paper"]', 'Organic', 'Wet (Green)', 'Dump grounds and unbleached paper filters straight into green bin.', 'Excellent source of nitrogen (greens) that accelerates thermophilic composting heat.', 'Keep separate from plastic pods.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-075', 'Tea Leaves & Unstapled Tea Bags', '["tea leaves", "used tea", "chai patti", "tea bag"]', 'Organic', 'Wet (Green)', 'Remove metal staple pin and synthetic tags. Place leaves in green bin.', 'Rapidly decomposes into natural soil conditioner.', 'Ensure tea bags do not contain synthetic nylon or polyester pyramid mesh.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-076', 'Crushed Eggshells', '["egg shells", "eggshell waste"]', 'Organic', 'Wet (Green)', 'Rinse lightly, crush with hands to speed calcium release, and add to compost.', 'Provides slow-release calcium carbonate vital for garden plant cell walls.', 'Crushing helps deter garden pests like slugs.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-077', 'Dry Fallen Leaves & Tree Clippings', '["dry leaves", "fallen leaves", "garden waste", "twigs"]', 'Organic', 'Wet (Green)', 'Collect in burlap sacks. Add as ''browns'' (carbon) to balance nitrogen food waste.', 'Essential carbon source for balanced aerobic hot composting.', 'NEVER burn dry leaves. Burning causes severe winter air pollution and PM2.5 smog.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-078', 'Fresh Lawn Grass Clippings', '["grass clippings", "mowed grass", "lawn waste"]', 'Organic', 'Wet (Green)', 'Spread in thin layers in compost or mulch directly around tree beds.', 'High moisture and nitrogen; decomposes within 10-14 days.', 'Avoid dumping thick wet piles without turning; can generate anaerobic odor.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-079', 'Coconut Shells & Coconut Husk (Coir)', '["coconut shell", "coir", "nariyal khol"]', 'Organic', 'Wet (Green)', 'Break shells into smaller pieces or take to municipal bio-mass centers.', 'Processed into coco-peat potting soil, briquettes, and activated carbon filters.', 'Very dense lignin takes 1-2 years to break down in standard home compost pits.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-080', 'Meat Bones & Fish Remains', '["meat bones", "chicken bones", "fish skeleton"]', 'Organic', 'Wet (Green)', 'Place in municipal wet waste bin (accepted in commercial industrial digesters).', 'Digested at high heat in municipal biomethanation plants or ground into bone meal fertilizer.', 'Do not add to open backyard compost piles as bones attract stray animals.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-081', 'Stale Bread, Rotis & Bakery Products', '["stale bread", "old roti", "bakery waste", "biscuit crumbs"]', 'Organic', 'Wet (Green)', 'Tear into pieces and add to green compost bin.', 'Breaks down rapidly into microbial nourishment.', 'Keep dry until composting to avoid premature black mold spores indoors.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-082', 'Used Wooden Toothpicks & Skewers', '["toothpick", "bamboo skewer", "wooden stick"]', 'Organic', 'Wet (Green)', 'Snap in half and add to green bin or compost bin.', '100% biodegradable natural wood fiber.', 'Ensure pointed ends are snapped so they do not pierce sanitation workers'' gloves.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-083', 'Natural Corn Cobs & Husks', '["corn cob", "bhutta husk", "maize waste"]', 'Organic', 'Wet (Green)', 'Chop cobs into disks and add to green bin.', 'Provides excellent aeration pockets inside compost piles.', 'Hard cobs take several months to fully disintegrate.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-084', 'Cut Flower Bouquets & Floral Offerings', '["flowers", "puja flowers", "wilted bouquet", "garland"]', 'Organic', 'Wet (Green)', 'Remove plastic wrapping ribbons and metal wires; drop flowers in green bin.', 'Converted into temple compost or natural incense sticks via civic initiatives.', 'Remove synthetic glitter and dye ribbons before composting.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-085', 'Raw Coconut Water Shell', '["green coconut", "tender coconut", "daak"]', 'Organic', 'Wet (Green)', 'Deposit at designated municipal green waste collection skips.', 'Shredded in municipal woodchippers for biomass fuel pellets and erosion control blankets.', 'Heavy weight; do not mix into fragile plastic curbside bins.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-086', 'Spent Lead-Acid Automotive Battery', '["car battery", "lead battery", "inverter battery", "ups battery"]', 'Hazardous', 'Hazardous (Red)', 'Store upright in acid-proof tray. Return to battery retailer under EPR buy-back rules.', 'Smelted at authorized secondary lead refineries; recovers 98% of lead plates and plastic casing.', 'Extremely corrosive sulfuric acid causes severe chemical burns. Lead causes nervous damage.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-087', 'Expired Chemical Pesticides & Herbicides', '["pesticide", "insecticide", "weed killer", "rat poison"]', 'Hazardous', 'Hazardous (Red)', 'Keep in original labeled container. Hand over exclusively to hazardous collection depots.', 'High temperature thermal destruction in specialized hazardous incinerators (>1100°C).', 'Never pour down storm drains, toilets, or onto open ground. Lethal to aquatic life and groundwater.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-088', 'Solvent-Based Oil Paint & Varnishes', '["oil paint", "varnish", "wood stain", "lacquer"]', 'Hazardous', 'Hazardous (Red)', 'Keep tightly sealed in can. Surrender to hazardous waste depot.', 'Solvents are recovered via industrial vacuum distillation; pigment solids used as fuel substitute.', 'Highly flammable vapors. Toxic when inhaled in enclosed spaces.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-089', 'Turpentine, Kerosene & Paint Thinner', '["thinner", "paint thinner", "turpentine", "mineral spirits"]', 'Hazardous', 'Hazardous (Red)', 'Seal bottle tightly with hazardous warning tape. Take to hazardous drop-off.', 'Repurposed as high-calorific fuel blend in industrial blast furnaces.', 'Volatile organic compounds (VOCs) ignite at low flashpoints. Store away from heat.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-090', 'Mercury Glass Medical Thermometer', '["mercury thermometer", "clinical thermometer"]', 'Hazardous', 'Hazardous (Red)', 'Store intact inside a plastic pill bottle padded with cotton. Take to hazardous center.', 'Pure elemental mercury is triple-distilled for industrial instrumentation.', 'If broken, do NOT vacuum or sweep with broom. Ventilate room, push beads with card into jar, seal.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-091', 'Fluorescent Tube Light & CFL Bulb', '["cfl", "tube light", "mercury vapor lamp", "fluorescent bulb"]', 'Hazardous', 'Hazardous (Red)', 'Keep intact inside original cardboard sleeve. Surrender to hazardous drop kiosk.', 'Automated crushing under negative pressure captures toxic mercury vapor and phosphor powder.', 'Broken tubes release neurotoxic mercury vapor. Open windows immediately if broken.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-092', 'Chemical Drain Cleaner (Lye/Sulfuric Acid)', '["drain cleaner", "caustic soda", "acid cleaner"]', 'Hazardous', 'Hazardous (Red)', 'Do not mix with other cleaners. Deliver to municipal hazardous waste drop-off.', 'Neutralized in specialized alkaline/acid treatment reactors.', 'Mixing with bleach generates deadly chlorine gas. Causes instantaneous severe tissue burns.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-093', 'Aerosol Spray Paint Cans', '["spray paint", "graffiti paint", "aerosol paint"]', 'Hazardous', 'Hazardous (Red)', 'Ensure empty; take to hazardous depot. Do not puncture.', 'Depressurized and metal reclaimed.', 'Explosion hazard if crushed in general municipal collection trucks.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-094', 'Mothballs & Naphthalene Balls', '["mothballs", "naphthalene", "camphor balls"]', 'Hazardous', 'Hazardous (Red)', 'Keep in airtight bag. Surrender to chemical waste collection point.', 'Incinerated in controlled chemical destruction chambers.', 'Naphthalene fumes cause hemolytic anemia and respiratory irritation; keep away from children.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-095', 'Corrosive Toilet Bowl Acid Cleaner (HCl)', '["toilet acid", "muriatic acid", "hydrochloric acid"]', 'Hazardous', 'Hazardous (Red)', 'Never discard down storm drains. Surrender remaining liquid at hazardous center.', 'Neutralized using lime slurry in municipal chemical treatment tanks.', 'Fumes irritate lungs; splash on skin causes chemical burns.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-096', 'Spent Chlorine Tablets & Pool Chemicals', '["chlorine tablets", "pool chemical", "bleach powder"]', 'Hazardous', 'Hazardous (Red)', 'Keep dry in original container. Hand over at hazardous station.', 'Controlled dilution and neutralization in effluent treatment plants.', 'Reacts violently with organic matter or acids to release toxic chlorine gas.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-097', 'PCB-Containing Fluorescent Ballasts', '["ballast", "light ballast", "choke"]', 'Hazardous', 'Hazardous (Red)', 'Deposit at hazardous electrical dismantling station.', 'Polychlorinated biphenyls (PCBs) require hazardous high-temperature plasma incineration.', 'PCBs are persistent bioaccumulative organic pollutants and human carcinogens.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-098', 'Expired Mosquito Vaporizer Liquid & Mats', '["all out liquid", "good knight refill", "mosquito refill"]', 'Hazardous', 'Hazardous (Red)', 'Keep capped in hazardous red bin. Do not throw in household wet bin.', 'Prallethrin and synthetic pyrethroids are incinerated under environmental supervision.', 'Toxic to cats, fish, and beneficial pollinating insects.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-099', 'Shoe Polish (Solvent/Paste Based)', '["shoe polish", "boot polish", "wax polish"]', 'Hazardous', 'Hazardous (Red)', 'Seal tin and discard in red hazardous stream.', 'Incinerated in municipal industrial incinerator.', 'Contains petroleum distillates and solvent dyes.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-100', 'Wood Preservative & Creosote Stains', '["creosote", "wood preservative", "termite chemical"]', 'Hazardous', 'Hazardous (Red)', 'Deliver tightly closed can to hazardous facility.', 'Treated in specialized industrial toxic waste cells.', 'Known carcinogen; avoid all skin contact.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-101', 'Expired Prescription Antibiotics & Tablets', '["pills", "medicines", "capsules", "expired tablets", "antibiotics"]', 'Biomedical', 'Hazardous (Red)', 'Keep in blister packs. Deposit in hospital take-back kiosk or municipal hazardous bin.', 'High-temperature medical incineration (1100°C) per CPCB Biomedical Waste Rules.', 'Never flush down toilet; pollutes rivers and breeds drug-resistant superbugs.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-102', 'Used Insulin Syringes & Needles (Sharps)', '["syringe", "insulin needle", "injection needle", "sharps"]', 'Biomedical', 'Hazardous (Red)', 'Place inside a puncture-proof thick plastic bottle or designated sharps box with lid taped shut.', 'Autoclaved at 121°C to sterilize pathogens, then shredded and encapsulated.', 'Extreme needle-stick risk. Can transmit HIV, Hepatitis B, and bloodborne viruses to sanitation staff.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-103', 'Blood-Soiled Cotton Bandages & Dressings', '["bandage", "gauze", "cotton dressing", "blood swab"]', 'Biomedical', 'Hazardous (Red)', 'Wrap securely in newspaper, mark with a red cross/dot, place in red bin.', 'Incinerated in bio-hazardous medical incinerators per BMW Rules 2016.', 'Biohazard. Infectious pathogens can survive on moist bandages for days.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-104', 'Used Disposable Surgical Masks (3-Ply/N95)', '["surgical mask", "face mask", "n95 mask", "medical mask"]', 'Biomedical', 'Hazardous (Red)', 'Cut ear loops with scissors (protects wildlife), wrap in paper, place in red bin.', 'Shredded and sterilized with high-pressure steam before disposal.', 'Do not throw loosely on streets or in open gutters.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-105', 'Used Latex & Nitrile Medical Gloves', '["surgical gloves", "rubber gloves", "latex gloves", "nitrile gloves"]', 'Biomedical', 'Hazardous (Red)', 'Peel off inside-out without touching exterior surface, place in hazardous red bin.', 'Treated with chemical disinfectant or autoclaving prior to shredding.', 'Non-biodegradable synthetic polymers; do not place in green wet waste.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-106', 'Expired Liquid Syrups & Suspensions', '["cough syrup", "tonic", "liquid medicine", "suspension"]', 'Biomedical', 'Hazardous (Red)', 'Leave in original glass or plastic bottle. Drop at pharmacy return bin.', 'Destroyed via rotary kiln medical incinerators.', 'Flushing down municipal sewer lines damages wastewater treatment bacteria.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-107', 'Intravenous (IV) Saline & Glucose Bags', '["iv bag", "saline bottle", "drip bag"]', 'Biomedical', 'Hazardous (Red)', 'Drain contents, place in biomedical collection stream.', 'Sterilized with chemical autoclaving and recycled into non-medical industrial PVC.', 'Ensure needle and cannula are detached and disposed in sharps container.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-108', 'Blood Lancet & Glucose Test Strips', '["lancet", "test strip", "glucometer strip", "diabetic needle"]', 'Biomedical', 'Hazardous (Red)', 'Place lancet cap back on. Seal in puncture-proof sharps bottle.', 'Sterilized and ground into inert medical residue.', 'Sharp points easily pierce plastic garbage liners.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-109', 'Expired Inhalers & Asthma Canisters', '["inhaler", "asthma pump", "salbutamol inhaler"]', 'Biomedical', 'Hazardous (Red)', 'Return to pharmacy or hazardous waste kiosk. Do not puncture canister.', 'HFA propellants are captured before metal canister recycling.', 'Pressurized canister can explode if placed in general incinerator.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-110', 'Disposable Urine & Catheter Drainage Bags', '["urine bag", "catheter bag", "drainage bag"]', 'Biomedical', 'Hazardous (Red)', 'Empty urine into toilet, wrap plastic bag in newspaper, mark red dot, place in red bin.', 'Autoclaved and shredded under strict hospital waste protocols.', 'High bacterial biohazard risk.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-111', 'Expired Ointments & Topical Creams', '["ointment", "antifungal cream", "medical gel", "steroid tube"]', 'Biomedical', 'Hazardous (Red)', 'Leave in tube, cap tightly, place in red hazardous bin.', 'Thermally decomposed in biomedical incinerators.', 'Active pharmaceutical ingredients harm aquatic micro-organisms if washed into sinks.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-112', 'Empty Blister Packs of Medicine', '["blister pack", "strip", "tablet wrapper", "pill foil"]', 'Biomedical', 'Dry (Blue)', 'Ensure all pills are removed. Place empty blister strip in blue dry bin.', 'Processed through delamination machines to separate aluminum foil and PVC plastic film.', 'Do not leave residual pills in pack.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-113', 'Dental Floss & Interdental Brushes', '["dental floss", "interdental brush", "floss pick"]', 'Biomedical', 'Dry (Blue)', 'Dispose in dry waste bin. Floss is nylon-coated Teflon.', 'Incinerated for energy recovery (RDF).', 'Never flush floss down toilet; binds with fat to create sewer fatbergs.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-114', 'Hospital Patient Identification Wristband', '["patient band", "id wristband", "hospital band"]', 'Biomedical', 'Dry (Blue)', 'Cut and destroy personal medical data, place in dry bin.', 'Recycled with synthetic vinyl and polyester.', 'Protects personal health data privacy.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-115', 'Expired Eye & Ear Drops', '["eye drops", "ear drops", "eyedrops bottle"]', 'Biomedical', 'Hazardous (Red)', 'Keep in bottle, discard in red hazardous bin.', 'Chemical components neutralized in biomedical incinerator.', 'Do not pour down drain.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-116', 'Old Smartphone & Mobile Handset', '["smartphone", "cellphone", "mobile phone", "iphone", "android"]', 'Electronic', 'E-Waste (Grey)', 'Perform full factory data reset, remove SIM/SD cards, deliver to EPR authorized kiosk.', 'High-tech hydrometallurgical processing recovers gold (0.034g), silver, copper, and rare-earth neodymium.', 'Never sell to informal scrap burners who use hazardous cyanide and nitric acid baths.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-117', 'Laptop Computer & Notebook', '["laptop", "notebook", "thinkpad", "macbook"]', 'Electronic', 'E-Waste (Grey)', 'Back up data and wipe drive. Hand over intact to certified e-waste dismantler.', 'Dismantled into aluminum chassis, copper heat pipes, motherboards, and battery cells.', 'Do not attempt to crush or puncture lithium battery embedded inside.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-118', 'Lithium-Ion Rechargeable Battery Pack', '["li-ion battery", "laptop battery", "power bank", "18650 cell"]', 'Electronic', 'E-Waste (Grey)', 'Tape over terminal contacts with insulation tape. Keep in dry container. Drop at e-waste hub.', 'Closed-loop recycling recovers cobalt, nickel, and battery-grade lithium carbonate.', 'High fire risk. Mechanical crushing causes immediate explosive thermal runaway.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-119', 'Computer Motherboard & Circuit Board (PCB)', '["motherboard", "circuit board", "pcb", "green board"]', 'Electronic', 'E-Waste (Grey)', 'Store in antistatic envelope. Deliver to certified e-waste recycling center.', 'Pyrometallurgical smelting reclaims precious gold, silver, palladium, and solder tin.', 'Contains lead solder and brominated flame retardants; toxic to burn.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-120', 'Alkaline AA / AAA / 9V Dry Cell Batteries', '["pencil battery", "dry cell", "remote battery", "duracell", "alkaline battery"]', 'Electronic', 'Hazardous (Red)', 'Tape contact ends to prevent short circuits. Drop in battery drop box.', 'Zinc and manganese oxides are extracted for agricultural fertilizers and steel alloying.', 'Corroded batteries leak potassium hydroxide caustic paste; handle with rubber gloves.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-121', 'Desktop Computer Monitor (LCD/LED/OLED)', '["monitor", "computer screen", "display", "led monitor"]', 'Electronic', 'E-Waste (Grey)', 'Keep screen intact to prevent glass breakage. Hand over to e-waste collector.', 'Backlight indium-tin-oxide, copper cabling, and optical diffusers are segregated.', 'Older monitors may contain CCFL mercury backlights; handle gently.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-122', 'Computer Keyboard & Optical Mouse', '["keyboard", "mouse", "usb mouse", "keypad"]', 'Electronic', 'E-Waste (Grey)', 'Wrap cord around device and deposit in e-waste bin.', 'ABS plastic casing and internal membrane circuit sheets are granulated for reuse.', 'Do not throw in household garbage.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-123', 'USB Charging Cables & Power Cords', '["charger cable", "usb cord", "lightning cable", "hdmi cable"]', 'Electronic', 'E-Waste (Grey)', 'Bundle with rubber band. Deliver to e-waste drop-off box.', 'Granulation plants strip PVC/TPE outer jacket and granulate 99% pure copper conductor.', 'Do not burn cables in open yard fires.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-124', 'Wi-Fi Router & Network Switch', '["router", "modem", "wifi box", "switch"]', 'Electronic', 'E-Waste (Grey)', 'Factory reset router to erase stored Wi-Fi credentials. Hand over to e-waste center.', 'Recovers copper connectors, transformer coils, and flame-retardant casing.', 'Erase network passwords before disposal.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-125', 'Old Microwave Oven', '["microwave", "oven", "kitchen appliance"]', 'Electronic', 'E-Waste (Grey)', 'Unplug, clean food grease, transport to appliance recovery depot.', 'Heavy copper transformer, capacitor, and steel enclosure are remelted.', 'DANGER: High-voltage capacitor retains lethal charge even when unplugged for weeks. Never dismantle magnetron.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-126', 'Electric Iron & Steam Press', '["iron", "steam iron", "clothes iron"]', 'Electronic', 'E-Waste (Grey)', 'Drain water tank, coil cord, take to e-waste center.', 'Cast aluminum soleplate, heating element, and thermostat bi-metal strips are recovered.', 'Let cool completely before packaging.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-127', 'Audio Earphones, Headphones & Earbuds', '["headphones", "earbuds", "airpods", "earphones"]', 'Electronic', 'E-Waste (Grey)', 'Keep in charging case. Take to e-waste collection kiosk.', 'Recovers miniature neodymium magnets, micro lithium batteries, and copper voice coils.', 'Tiny wireless earbuds contain micro lithium cells that burn if compacted.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-128', 'Smartwatch & Fitness Tracker Band', '["smartwatch", "fitness band", "apple watch", "fitbit"]', 'Electronic', 'E-Waste (Grey)', 'Factory reset, detach silicone wristband (band to plastic stream), watch to e-waste.', 'High density electronic miniaturization recovery.', 'Erase health and biometric personal data.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-129', 'Tablet Computer & iPad', '["tablet", "ipad", "kindle", "e-reader"]', 'Electronic', 'E-Waste (Grey)', 'Erase personal account, place in e-waste bin.', 'High recovery yield of lithium, cobalt, and display components.', 'Do not bend or puncture swollen battery displays.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-130', 'Television Set (LED/Smart TV)', '["television", "tv", "smart tv"]', 'Electronic', 'E-Waste (Grey)', 'Transport screen face-up, protected with blanket. Hand over to municipal bulk e-waste service.', 'Circuit boards, power supply capacitors, and structural chassis are recycled.', 'Heavy weight; call municipal bulk pickup.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-131', 'Concrete Rubble & Broken Paver Blocks', '["concrete", "rubble", "cement chunks", "paver block"]', 'Construction', 'Construction (Dry)', 'Segregate from municipal trash. Transport to designated municipal C&D Waste Processing Plant.', 'Crushed in impact crushers to produce Recycled Concrete Aggregate (RCA) and manufactured sand (M-Sand).', 'Dumping concrete in stormwater drains or vacant plots is a punishable offense under C&D Waste Rules.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-132', 'Broken Ceramic Floor & Wall Tiles', '["ceramic tiles", "broken tile", "vitrified tile", "mosaic"]', 'Construction', 'Construction (Dry)', 'Collect in sturdy gunny bags; deliver to C&D processing facility.', 'Crushed into sub-base aggregate for road construction and interlocking paver block mix.', 'Sharp tile edges slice through standard footwear; wear steel-toed boots.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-133', 'Gypsum Drywall & Plasterboard Scraps', '["drywall", "gypsum board", "plasterboard", "sheetrock"]', 'Construction', 'Construction (Dry)', 'Keep dry and separate from wet cement; deliver to gypsum recyclers.', 'Crushed and calcinated back into new gypsum plaster and soil amendment.', 'If buried in wet municipal landfills, gypsum decomposes into smelly toxic hydrogen sulfide gas.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-134', 'Asphalt Roofing Shingles & Road Millings', '["asphalt", "shingles", "tar chunks", "bitumen"]', 'Construction', 'Construction (Dry)', 'Collect without dirt contamination; take to asphalt batching plant.', 'Heated and re-blended into Reclaimed Asphalt Pavement (RAP) for highway resurfacing.', 'Keep free of combustible wood debris.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-135', 'Mineral Glass Wool Insulation', '["glass wool", "rock wool", "fiberglass insulation"]', 'Construction', 'Construction (Dry)', 'Pack tightly into double-sealed heavy duty plastic bags.', 'Melted in high-temperature glass furnaces for industrial refractory brick binding.', 'Glass fibers cause severe respiratory irritation and skin itch. Wear N95 respirator and gloves.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-136', 'Red Clay Bricks & Broken Masonry', '["brick", "red brick", "masonry rubble", "mortar"]', 'Construction', 'Construction (Dry)', 'Clean mortar if feasible for brick reuse; rubble goes to C&D plant.', 'Ground into surkhi powder for lime mortar and drainage backfill aggregate.', 'Do not mix with household domestic waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-137', 'PVC Plumbing Conduit & Drainage Offcuts', '["pvc scrap", "pipe offcuts", "conduit scrap"]', 'Construction', 'Construction (Dry)', 'Separate from mortar; bundle together.', 'Granulated for non-pressure sewage pipe manufacturing.', 'Keep free of wet plaster.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-138', 'Broken Marble & Granite Slab Trimmings', '["marble", "granite", "stone slab", "countertop scrap"]', 'Construction', 'Construction (Dry)', 'Deliver to stone crushing units or mosaic artisans.', 'Crushed into terrazzo flooring chips, decorative garden gravel, and stone slurry lime.', 'Heavy weight; secure vehicle load during transit.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-139', 'Sand & Silt Excavation Spoils', '["sand", "silt", "digging soil", "excavation dirt"]', 'Construction', 'Construction (Dry)', 'Transport to municipal low-lying land reclamation or brick kilns.', 'Used for civil road sub-grades and embankment stabilization.', 'Ensure soil is free from industrial chemical contamination.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-140', 'Mortar & Plaster Lumps', '["mortar", "plaster scrap", "cured cement"]', 'Construction', 'Construction (Dry)', 'Deliver to C&D aggregate crushing station.', 'Crushed for unpaved road base layers.', 'Do not throw in household garbage bins.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-141', 'Asbestos Cement Roofing Sheets (Dangerous)', '["asbestos sheet", "corrugated cement sheet", "asbestos"]', 'Construction', 'Hazardous (Red)', 'WET THOROUGHLY to prevent airborne dust. Never saw or break. Wrap in 200-micron polythene, label HAZARDOUS ASBESTOS.', 'Disposed exclusively in dedicated engineered hazardous landfill cells with GPS tracking.', 'LETHAL INHALATION HAZARD. Inhaled asbestos fibers cause incurable mesothelioma lung cancer.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-142', 'Hardened Leftover Cement Bags', '["caked cement", "hard cement", "spoiled cement"]', 'Construction', 'Construction (Dry)', 'Crush hard lumps for foundation fill. Paper sack goes to paper recycling.', 'Used as road foundation base rock.', 'Keep cement dust out of eyes and airways.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-143', 'Ceramic Sanitaryware (Broken Toilet Bowl/Sink)', '["commode", "sink", "washbasin", "ceramic sanitary"]', 'Construction', 'Construction (Dry)', 'Deliver to C&D recycling yard. Wear goggles when handling.', 'Ground into fine refractory powder for ceramic kiln furniture.', 'Vitreous china shards are razor-sharp.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-144', 'Plywood & Particle Board Construction Offcuts', '["plywood scrap", "mdf offcut", "particle board"]', 'Construction', 'Construction (Dry)', 'Keep separate from untreated wood. Take to biomass boiler facility.', 'Burned in industrial boilers equipped with toxic urea-formaldehyde scrubbers.', 'Do not burn in home fireplaces or campfires; emits toxic formaldehyde fumes.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-145', 'Tar Paper & Waterproofing Bituminous Felt', '["tar paper", "bitumen sheet", "waterproofing membrane"]', 'Construction', 'Construction (Dry)', 'Roll neatly; take to commercial demolition waste depot.', 'Blended with road asphalt binder.', 'Combustible; keep away from open flames.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-146', 'Old Cotton Clothes & T-Shirts', '["cotton shirt", "old clothes", "jeans", "cotton fabric", "t-shirt"]', 'Textile', 'Textile (Dry)', 'Wash, dry, and fold. If wearable, donate to charity; torn garments go to textile recovery.', 'Mechanically shredded into recycled cotton fiber for insulation, soundproofing, and wiping rags.', 'Ensure clothes are clean and dry; damp fabric rots and produces mold in transit.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-147', 'Polyester Sportswear & Fleece Jackets', '["polyester", "fleece", "synthetic clothes", "nylon shirt"]', 'Textile', 'Textile (Dry)', 'Donate wearable items. Worn out items go to dry textile bins.', 'Chemically depolymerized or shredded into carpet underlay and acoustic automotive pads.', 'Synthetic fibers shed microplastics; wash inside a filter bag.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-148', 'Worn Out Sneakers & Athletic Shoes', '["sneakers", "shoes", "running shoes", "footwear"]', 'Textile', 'Household (Dry)', 'Tie pair together with laces. Drop in footwear recycling collection boxes.', 'Separated into rubber soles (crushed for playground turf) and fabric uppers.', 'Do not throw in wet waste.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-149', 'Leather Belts, Shoes & Wallets', '["leather belt", "leather shoes", "leather wallet", "handbag"]', 'Textile', 'Textile (Dry)', 'Donate usable items. Damaged leather surrender to specialty leather crafts.', 'Ground into bonded leather composite sheets for footwear counters and bookbinding.', 'Chromium-tanned leather should not be incinerated outdoors.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-150', 'Wool Sweaters & Blankets', '["wool sweater", "woolen blanket", "shawl", "cardigan"]', 'Textile', 'Textile (Dry)', 'Wash and air-dry. Surrender to wool reclamation centers.', 'Shredded into premium reclaimed shoddy wool for winter relief blankets and yarn.', 'Wool is naturally flame-resistant and biodegradable.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-151', 'Nylon Curtains & Window Drapes', '["curtains", "drapes", "nylon fabric"]', 'Textile', 'Textile (Dry)', 'Remove plastic curtain rings and hooks; fold neatly in dry bin.', 'Repelletized into engineering nylon pellets for automotive zip ties and gears.', 'Ensure metal hooks are detached.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-152', 'Denim Jeans & Jackets', '["denim", "blue jeans", "jean jacket"]', 'Textile', 'Textile (Dry)', 'Donate usable jeans. Shredded scrap makes home thermal insulation.', 'Extremely durable cotton fibers are recycled into denim building insulation batting.', 'Remove large metal buckles if feasible.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-153', 'Silk Sarees & Silk Garments', '["silk saree", "silk dress", "pure silk"]', 'Textile', 'Textile (Dry)', 'Heritage sarees can be upcycled into cushion covers; scraps go to textile recycling.', 'Natural protein fibers are re-spun into luxury blended textiles.', 'Zari border metal threads can be reclaimed for silver content.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-154', 'Synthetic Microfiber Cleaning Cloths', '["microfiber cloth", "cleaning rag", "duster"]', 'Textile', 'Textile (Dry)', 'Rinse dirt, dry, and place in dry recyclables.', 'Used in industrial machinery oil wipes.', 'Do not mix with organic compost.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-155', 'Old Bed Sheets & Pillowcases', '["bedsheet", "pillow cover", "bed linen"]', 'Textile', 'Textile (Dry)', 'Launder and donate to animal shelters for bedding, or place in textile bin.', 'Cut into industrial cleaning rags for mechanics and workshops.', 'Animal shelters eagerly accept old clean bedsheets.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-156', 'Jute Gunny Sacks & Burlap Bags', '["gunny bag", "jute sack", "burlap"]', 'Textile', 'Organic / Wet (Green)', 'Shake out grain dust. Composts naturally or reuse for garden mulch.', '100% natural bast fiber; enriches soil aeration and compost carbon balance.', 'Natural jute is fully eco-friendly.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-157', 'Mattress Polyurethane Foam', '["foam", "mattress foam", "sponge cushion"]', 'Textile', 'Textile (Dry)', 'Strip fabric cover; take foam core to commercial foam densifier.', 'Shredded and bonded under heat to create bonded foam for gym mats and carpet cushion.', 'Highly flammable; keep away from open sparks.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-158', 'Socks & Undergarments (Worn Out)', '["socks", "underwear", "worn socks"]', 'Textile', 'Textile (Dry)', 'Wash clean. Drop in textile recovery bins for industrial wiping cloth shredding.', 'Shredded for automotive acoustic insulation and paper pulp additives.', 'Must be laundered before recycling handover.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-159', 'Umbrella Fabric (Waterproof Nylon)', '["umbrella", "rain umbrella"]', 'Textile', 'Textile (Dry)', 'Separate metal steel rib frame (to metal bin) from nylon canopy cloth.', 'Steel frame is melted; waterproof nylon is downcycled.', 'Sharp metal ribs must be tied safely.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-160', 'Cloth Shopping & Canvas Tote Bags', '["tote bag", "canvas bag", "cloth bag"]', 'Textile', 'Textile (Dry)', 'Reuse hundreds of times; damaged bags drop in textile collection.', 'Recycled into recycled cotton yarn and heavyweight canvas.', 'Best sustainable replacement for single-use polythene.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-161', 'Ceramic Coffee Mugs & Crockery', '["ceramic mug", "cup", "ceramic plate", "crockery", "clay pot"]', 'Household', 'Household (Dry)', 'If chipped or broken, wrap in paper and place in blue dry bin.', 'Crushed for refractory road sub-base and drainage aggregate.', 'Ceramic cannot be melted with container glass. Do not mix with beer/soda bottles.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-162', 'Incandescent Filament Light Bulb', '["bulb", "tungsten bulb", "lamp", "filament bulb"]', 'Household', 'Household (Dry)', 'Wrap in paper and place in dry bin. Does NOT contain mercury.', 'Metal screw base is recycled for brass/aluminum; filament glass is downcycled.', 'Distinct from fluorescent CFL bulbs which are toxic Hazardous (Red).', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-163', 'Synthetic Kitchen Washing Sponge', '["scrub pad", "kitchen sponge", "scotch brite"]', 'Household', 'Household (Dry)', 'Rinse out food oils, wring dry, discard in dry bin.', 'Composite polyurethane and polyester; incinerated for energy recovery (RDF).', 'Harbors bacteria; replace every 3-4 weeks. Cannot be composted.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-164', 'Used Cigarette Butts & Filters', '["cigarette butt", "filter", "smoke butt"]', 'Household', 'Household (Dry)', 'Ensure fully extinguished with water before discarding.', 'Cellulose acetate plastic filters are chemically recycled into paper pulp and plastic pellets.', 'Contains toxic nicotine and arsenic; never toss into nature or storm drains.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-165', 'Disposable Baby Diapers & Adult Incontinence Pads', '["diaper", "baby diaper", "huggies", "pampers"]', 'Household', 'Hazardous (Red)', 'Scrape solid fecal matter into toilet, wrap soiled diaper tightly, place in red bin.', 'High-temperature sanitary incineration or specialized autoclave pyrolysis.', 'Major biohazard. Never flush down toilet. Takes 500+ years to degrade in landfills.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-166', 'Used Sanitary Pads & Tampons', '["sanitary pad", "tampon", "menstrual pad", "whisper", "stayfree"]', 'Household', 'Hazardous (Red)', 'Wrap securely in marked newspaper with a prominent RED DOT. Place in Red Bin.', 'Destroyed in centralized municipal incinerators at 900°C per SWM Rules 2016.', 'Never throw in open or flush in toilets; causes severe sewer line blockages.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-167', 'Vacuum Cleaner Dust & Sweeping Dirt', '["dust", "vacuum dirt", "floor sweeping"]', 'Household', 'Household (Dry)', 'Pack inside a paper bag and seal before putting in dry waste.', 'Diverted to landfill capping or waste-to-energy.', 'Loose dust can blow into sanitation workers'' eyes and lungs.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-168', 'Wax Crayons & Coloring Pastels', '["crayons", "wax crayon", "oil pastel"]', 'Household', 'Household (Dry)', 'Melt stubs together into new multi-color crayons, or dispose in dry bin.', 'Paraffin wax can be recovered by specialty school charity drives.', 'Non-toxic to children; keep away from heat.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-169', 'Broken Umbrella Metal Skeleton', '["umbrella ribs", "broken umbrella"]', 'Household', 'Dry (Blue)', 'Separate fabric; fold metal spokes and tie securely.', 'Ferrous steel scrap is melted down.', 'Spokes can puncture collection bags.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-170', 'Plastic Ballpoint Pens & Empty Refills', '["pen", "ball pen", "refill"]', 'Household', 'Dry (Blue)', 'Drop in plastic collection bin. Switch to refillable fountain pens.', 'Polycarbonate barrel is granulated.', 'Small plastic items accumulate quickly; collect in bulk before disposal.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-171', 'Candle Wax Stubs & Drippings', '["candle wax", "paraffin wax"]', 'Household', 'Household (Dry)', 'Melt down to make new emergency candles, or place in dry bin.', 'Reprocessed into industrial lubricants and fuel blocks.', 'Do not throw in organic wet bin.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-172', 'Empty Deodorant Roll-On Bottle', '["roll on", "rollon bottle"]', 'Household', 'Dry (Blue)', 'Pop out plastic roller ball, rinse liquid residue, place in blue bin.', 'High grade PP and HDPE are recycled.', 'Separate ball and bottle for optimal sorting.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-173', 'Plastic Clothespins & Pegs', '["clothespin", "clothes peg"]', 'Household', 'Dry (Blue)', 'Remove small metal spring wire; place plastic in blue bin.', 'Reprocessed into utility plastic products.', 'Separate metal and plastic components.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-174', 'Used Rubber Bands (Natural/Synthetic)', '["rubber band", "elastic band"]', 'Household', 'Household (Dry)', 'Store for reuse. Worn degraded rubber place in dry waste bin.', 'Synthetic elastomers are compounded for rubberized asphalt.', 'Keep away from sunlight to avoid brittleness.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-175', 'Synthetic Wet Wipes (Baby Wipes/Facial Wipes)', '["wet wipes", "baby wipes", "facial wipes"]', 'Household', 'Household (Dry)', 'Discard in dry bin. NEVER flush in toilet bowl.', 'Made of woven plastic microfibers (polyester) that do NOT break down in water.', 'Flushing wipes causes catastrophic sewer pump blockages and city fatbergs.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-176', 'Used Vulcanized Car & Motorcycle Tires', '["tyre", "tire", "car tyre", "rubber tyre"]', 'Automotive', 'Automotive (Dry)', 'Surrender to tire dealer under EPR Tire Regulations. Never burn.', 'Shredded into crumb rubber for athletic running tracks, playground turf, and rubberized asphalt.', 'Burning tires releases thick toxic black smoke, benzene, sulfur dioxide, and mutagenic oils.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-177', 'Used Engine Motor Oil (Lubricant)', '["engine oil", "motor oil", "used oil", "mobil oil"]', 'Automotive', 'Hazardous (Red)', 'Drain into a sealed container. Hand over exclusively to authorized used oil re-refiners.', 'Vacuum re-refining produces high-grade Group II base oils, saving virgin petroleum.', '1 liter of used motor oil can contaminate 1 million liters of clean freshwater. Highly toxic.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-178', 'Engine Oil Filters (Metal & Paper Core)', '["oil filter", "car filter"]', 'Automotive', 'Hazardous (Red)', 'Puncture dome and hot-drain residual oil for 24 hours into waste oil container.', 'Crushed to extract remaining oil; steel shell is melted down in foundries.', 'Contains entrapped hazardous petroleum sludge.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-179', 'Ethylene Glycol Engine Coolant & Antifreeze', '["coolant", "antifreeze", "radiator fluid"]', 'Automotive', 'Hazardous (Red)', 'Store in dedicated labeled container. Deliver to automotive hazardous station.', 'Fractional distillation recovers pure ethylene glycol for reuse.', 'Sweet taste is EXTREMELY POISONOUS to children and pets. Causes fatal kidney failure.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-180', 'Automotive Asbestos-Free Brake Pads', '["brake pad", "brake shoe", "brake lining"]', 'Automotive', 'Automotive (Dry)', 'Collect in heavy box; deposit at automotive scrap recycling facility.', 'Metallic friction compounds and backing steel plates are separated magnetically.', 'Brake dust contains fine particulate matter; do not blow with compressed air.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-181', 'Automotive Windshield Wiper Blades', '["wiper blade", "wiper rubber", "car wiper"]', 'Automotive', 'Automotive (Dry)', 'Separate metal frame from silicone/rubber insert.', 'Metal arms are recycled; rubber inserts are downcycled.', 'Replace blades annually for road safety.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-182', 'Automotive Lead-Acid Starter Battery', '["car battery", "auto battery", "12v battery"]', 'Automotive', 'Hazardous (Red)', 'Surrender to battery vendor for statutory cash refund/buy-back credit.', 'Lead plates are melted in smelters; acid is neutralized into sodium sulfate.', 'Never dump battery acid into sewer.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-183', 'Automotive Catalytic Converter', '["catalytic converter", "cat con", "exhaust catalyst"]', 'Automotive', 'Automotive (Dry)', 'Deliver intact to licensed precious metals auto dismantler.', 'Contains high-value platinum, palladium, and rhodium catalyst metals.', 'Theft target; keep stored securely before recycling handover.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-184', 'Laminated Automotive Windshield Safety Glass', '["windshield", "car windshield", "windscreen"]', 'Automotive', 'Automotive (Dry)', 'Deliver to specialized automotive glass dismantler.', 'Mechanical peelers strip the flexible polyvinyl butyral (PVB) interlayer from glass.', 'Cannot be melted in standard bottle glass furnaces.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-185', 'Used Spark Plugs', '["spark plug"]', 'Automotive', 'Automotive (Dry)', 'Collect with scrap metals in blue bin.', 'High alumina ceramic insulator and nickel-alloy electrodes are reclaimed.', 'Heavy metal scrap value.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-186', 'Automotive Shock Absorber Struts', '["shock absorber", "strut", "suspension"]', 'Automotive', 'Automotive (Dry)', 'Relieve internal pressure and drain hydraulic oil before scrap handover.', 'High strength steel cylinders are remelted in electric arc furnaces.', 'Pressurized gas units can explode if sheared without prior de-gassing.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-187', 'Used Transmission & Gearbox Fluid', '["transmission fluid", "atf", "gear oil"]', 'Automotive', 'Hazardous (Red)', 'Collect in leak-proof jug; return to oil recycling station.', 'Re-refined into industrial grade hydraulic and gear oils.', 'Harms soil microbiology if spilled.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-188', 'Vehicle Air Filter (Pleated Paper)', '["air filter", "car air filter"]', 'Automotive', 'Automotive (Dry)', 'Knock out dry dust, discard in dry waste bin.', 'Polyurethane frame and paper element are processed for energy recovery (RDF).', 'Dirty filters should not be washed and reused.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-189', 'Automotive Alternator & Starter Motor', '["alternator", "starter motor", "dynamo"]', 'Automotive', 'E-Waste (Grey)', 'Surrender to electrical rebuilder or e-waste recycling depot.', 'Heavy copper stator windings and aluminum housing hold prime scrap recovery value.', 'High recovery value.', 'e_waste', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-190', 'Blown Automotive Headlamp Bulbs (Halogen/Xenon)', '["headlight bulb", "car bulb", "halogen bulb"]', 'Automotive', 'Hazardous (Red)', 'Wrap in paper, dispose in hazardous stream.', 'Quartz glass and tungsten filament are reclaimed.', 'Xenon HID bulbs contain high internal gas pressure.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-191', 'Industrial Wooden Shipping Pallets', '["pallet", "wooden pallet", "skid", "wood crate"]', 'Industrial', 'Industrial (Dry)', 'Repair damaged slats for reuse; unrepairable pallets chip into wood mulch.', 'Shredded into boiler fuel biomass, particle board feedstock, and landscape mulch.', 'Inspect for ''HT'' stamp (Heat Treated). Avoid chemically treated ''MB'' (Methyl Bromide) pallets.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-192', 'Pulverized Coal Fly Ash', '["fly ash", "coal ash", "thermal ash"]', 'Industrial', 'Industrial (Dry)', 'Store in sealed dry silo. Transport in closed bulk tankers.', 'Mandatory component in eco-friendly Pozzolana Portland Cement (PPC) and fly ash bricks.', 'Inhaling dry airborne ash dust causes silicosis and lung damage.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-193', 'Metal Machining Swarf & Shavings', '["swarf", "metal shavings", "borings", "turnings", "drill shavings"]', 'Industrial', 'Industrial (Dry)', 'Centrifuge to remove cutting oil fluids; compress into dense briquettes for smelting.', 'Melted in foundry cupolas with minimal oxidation loss.', 'Swarf coated in flammable cutting oils can spontaneously combust in piles.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-194', 'Spent Foundry Casting Sand', '["foundry sand", "casting sand", "silica sand"]', 'Industrial', 'Industrial (Dry)', 'Collect after casting; deliver to asphalt or concrete batching plants.', 'Substitutes virgin sand in sub-base road construction and asphalt concrete mixes.', 'Ensure sand is tested for heavy metal binder leachability before civil use.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-195', 'Heavy Industrial Plastic Strapping (PET/PP)', '["strapping", "packaging strap", "crate band"]', 'Industrial', 'Industrial (Dry)', 'Cut into lengths under 30cm, bundle tightly in blue dry bin.', 'Granulated and extruded into new industrial packaging strapping.', 'Long uncut straps tangle and damage industrial shredder rotating shafts.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-196', 'Electroplating Chemical Sludge', '["plating sludge", "galvanic sludge", "metal sludge"]', 'Industrial', 'Hazardous (Red)', 'Dewater sludge using filter press. Store in labeled hazardous containers.', 'Disposed at authorized Common Hazardous Waste Treatment, Storage & Disposal Facilities (TSDF).', 'Contains lethal concentrations of cyanide, hexavalent chromium, and heavy metals.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-197', 'Spent Electrical Transformer Oil', '["transformer oil", "dielectric oil"]', 'Industrial', 'Hazardous (Red)', 'Test for PCB contamination before handling. Hand over to specialized recycler.', 'Dehydrated, degassed, and vacuum filtered back to dielectric breakdown specifications.', 'PCBs in older transformer oils are persistent toxic carcinogens.', 'hazardous', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-198', 'Industrial Desiccant Silica Gel Bags', '["silica gel", "desiccant", "moisture absorber"]', 'Industrial', 'Industrial (Dry)', 'Reactivate by heating in oven at 110°C, or discard in dry bin.', 'Inert synthetic silica beads can be reused multiple moisture cycles.', 'Do not ingest. Cobalt chloride indicator beads are toxic; prefer orange indicators.', 'dustbin', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
INSERT INTO waste_items (id, name, aliases, category, segregation_bin, disposal_method, recycling_guidance, safety_precautions, target_facility_code, created_at, updated_at) VALUES ('waste-199', 'Industrial Grinding & Abrasive Wheels', '["grinding wheel", "cut off wheel", "abrasive disc"]', 'Industrial', 'Industrial (Dry)', 'Wrap worn discs, discard in industrial dry bin.', 'Crushed for silicon carbide and aluminum oxide industrial abrasive fillers.', 'Damaged wheels can shatter at high speed; never reuse cracked discs.', 'recycling', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, disposal_method=EXCLUDED.disposal_method;
